SELECT _SchemaName = s.[name]
    , _ObjectName = o.[name]
    , _ObjectType = o.[type]
    , _RowHash = CONVERT(binary(32), HASHBYTES('SHA2_256', (SELECT x.* FROM (SELECT NULL) n(n) FOR JSON AUTO)))
    --
    , x.*
FROM sys.objects o
    JOIN sys.schemas s ON s.[schema_id] = o.[schema_id]
    CROSS APPLY (
        SELECT BaseType                             = OBJECTPROPERTYEX(o.[object_id], 'BaseType')
            , CnstIsClustKey                        = OBJECTPROPERTYEX(o.[object_id], 'CnstIsClustKey')
            , CnstIsColumn                          = OBJECTPROPERTYEX(o.[object_id], 'CnstIsColumn')
            , CnstIsDeleteCascade                   = OBJECTPROPERTYEX(o.[object_id], 'CnstIsDeleteCascade')
            , CnstIsDisabled                        = OBJECTPROPERTYEX(o.[object_id], 'CnstIsDisabled')
            , CnstIsNonclustKey                     = OBJECTPROPERTYEX(o.[object_id], 'CnstIsNonclustKey')
            , CnstIsNotRepl                         = OBJECTPROPERTYEX(o.[object_id], 'CnstIsNotRepl')
            , CnstIsNotTrusted                      = OBJECTPROPERTYEX(o.[object_id], 'CnstIsNotTrusted')
            , CnstIsUpdateCascade                   = OBJECTPROPERTYEX(o.[object_id], 'CnstIsUpdateCascade')
            , ExecIsAfterTrigger                    = OBJECTPROPERTYEX(o.[object_id], 'ExecIsAfterTrigger')
            , ExecIsAnsiNullsOn                     = OBJECTPROPERTYEX(o.[object_id], 'ExecIsAnsiNullsOn')
            , ExecIsDeleteTrigger                   = OBJECTPROPERTYEX(o.[object_id], 'ExecIsDeleteTrigger')
            , ExecIsFirstDeleteTrigger              = OBJECTPROPERTYEX(o.[object_id], 'ExecIsFirstDeleteTrigger')
            , ExecIsFirstInsertTrigger              = OBJECTPROPERTYEX(o.[object_id], 'ExecIsFirstInsertTrigger')
            , ExecIsFirstUpdateTrigger              = OBJECTPROPERTYEX(o.[object_id], 'ExecIsFirstUpdateTrigger')
            , ExecIsInsertTrigger                   = OBJECTPROPERTYEX(o.[object_id], 'ExecIsInsertTrigger')
            , ExecIsInsteadOfTrigger                = OBJECTPROPERTYEX(o.[object_id], 'ExecIsInsteadOfTrigger')
            , ExecIsLastDeleteTrigger               = OBJECTPROPERTYEX(o.[object_id], 'ExecIsLastDeleteTrigger')
            , ExecIsLastInsertTrigger               = OBJECTPROPERTYEX(o.[object_id], 'ExecIsLastInsertTrigger')
            , ExecIsLastUpdateTrigger               = OBJECTPROPERTYEX(o.[object_id], 'ExecIsLastUpdateTrigger')
            , ExecIsQuotedIdentOn                   = OBJECTPROPERTYEX(o.[object_id], 'ExecIsQuotedIdentOn')
            , ExecIsStartup                         = OBJECTPROPERTYEX(o.[object_id], 'ExecIsStartup')
            , ExecIsTriggerDisabled                 = OBJECTPROPERTYEX(o.[object_id], 'ExecIsTriggerDisabled')
            , ExecIsTriggerNotForRepl               = OBJECTPROPERTYEX(o.[object_id], 'ExecIsTriggerNotForRepl')
            , ExecIsUpdateTrigger                   = OBJECTPROPERTYEX(o.[object_id], 'ExecIsUpdateTrigger')
            , ExecIsWithNativeCompilation           = OBJECTPROPERTYEX(o.[object_id], 'ExecIsWithNativeCompilation')
            , HasAfterTrigger                       = OBJECTPROPERTYEX(o.[object_id], 'HasAfterTrigger')
            , HasDeleteTrigger                      = OBJECTPROPERTYEX(o.[object_id], 'HasDeleteTrigger')
            , HasInsertTrigger                      = OBJECTPROPERTYEX(o.[object_id], 'HasInsertTrigger')
            , HasInsteadOfTrigger                   = OBJECTPROPERTYEX(o.[object_id], 'HasInsteadOfTrigger')
            , HasUpdateTrigger                      = OBJECTPROPERTYEX(o.[object_id], 'HasUpdateTrigger')
            , IsAnsiNullsOn                         = OBJECTPROPERTYEX(o.[object_id], 'IsAnsiNullsOn')
            , IsCheckCnst                           = OBJECTPROPERTYEX(o.[object_id], 'IsCheckCnst')
            , IsConstraint                          = OBJECTPROPERTYEX(o.[object_id], 'IsConstraint')
            , IsDefault                             = OBJECTPROPERTYEX(o.[object_id], 'IsDefault')
            , IsDefaultCnst                         = OBJECTPROPERTYEX(o.[object_id], 'IsDefaultCnst')
            , IsDeterministic                       = OBJECTPROPERTYEX(o.[object_id], 'IsDeterministic')
            , IsEncrypted                           = OBJECTPROPERTYEX(o.[object_id], 'IsEncrypted')
            , IsExecuted                            = OBJECTPROPERTYEX(o.[object_id], 'IsExecuted')
            , IsExtendedProc                        = OBJECTPROPERTYEX(o.[object_id], 'IsExtendedProc')
            , IsForeignKey                          = OBJECTPROPERTYEX(o.[object_id], 'IsForeignKey')
            , IsIndexed                             = OBJECTPROPERTYEX(o.[object_id], 'IsIndexed')
            , IsIndexable                           = OBJECTPROPERTYEX(o.[object_id], 'IsIndexable')
            , IsInlineFunction                      = OBJECTPROPERTYEX(o.[object_id], 'IsInlineFunction')
            , IsMSShipped                           = OBJECTPROPERTYEX(o.[object_id], 'IsMSShipped')
            , IsPrecise                             = OBJECTPROPERTYEX(o.[object_id], 'IsPrecise')
            , IsPrimaryKey                          = OBJECTPROPERTYEX(o.[object_id], 'IsPrimaryKey')
            , IsProcedure                           = OBJECTPROPERTYEX(o.[object_id], 'IsProcedure')
            , IsQuotedIdentOn                       = OBJECTPROPERTYEX(o.[object_id], 'IsQuotedIdentOn')
            , IsQueue                               = OBJECTPROPERTYEX(o.[object_id], 'IsQueue')
            , IsReplProc                            = OBJECTPROPERTYEX(o.[object_id], 'IsReplProc')
            , IsRule                                = OBJECTPROPERTYEX(o.[object_id], 'IsRule')
            , IsScalarFunction                      = OBJECTPROPERTYEX(o.[object_id], 'IsScalarFunction')
            , IsSchemaBound                         = OBJECTPROPERTYEX(o.[object_id], 'IsSchemaBound')
            , IsSystemTable                         = OBJECTPROPERTYEX(o.[object_id], 'IsSystemTable')
            , IsSystemVerified                      = OBJECTPROPERTYEX(o.[object_id], 'IsSystemVerified')
            , IsTable                               = OBJECTPROPERTYEX(o.[object_id], 'IsTable')
            , IsTableFunction                       = OBJECTPROPERTYEX(o.[object_id], 'IsTableFunction')
            , IsTrigger                             = OBJECTPROPERTYEX(o.[object_id], 'IsTrigger')
            , IsUniqueCnst                          = OBJECTPROPERTYEX(o.[object_id], 'IsUniqueCnst')
            , IsUserTable                           = OBJECTPROPERTYEX(o.[object_id], 'IsUserTable')
            , IsView                                = OBJECTPROPERTYEX(o.[object_id], 'IsView')
            , OwnerId                               = OBJECTPROPERTYEX(o.[object_id], 'OwnerId')
            , SchemaId                              = OBJECTPROPERTYEX(o.[object_id], 'SchemaId')
            , SystemDataAccess                      = OBJECTPROPERTYEX(o.[object_id], 'SystemDataAccess')
            , TableDeleteTrigger                    = OBJECTPROPERTYEX(o.[object_id], 'TableDeleteTrigger')
            , TableDeleteTriggerCount               = OBJECTPROPERTYEX(o.[object_id], 'TableDeleteTriggerCount')
            , TableFullTextMergeStatus              = OBJECTPROPERTYEX(o.[object_id], 'TableFullTextMergeStatus')
            , TableFullTextBackgroundUpdateIndexOn  = OBJECTPROPERTYEX(o.[object_id], 'TableFullTextBackgroundUpdateIndexOn')
            , TableFulltextCatalogId                = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextCatalogId')
            , TableFullTextChangeTrackingOn         = OBJECTPROPERTYEX(o.[object_id], 'TableFullTextChangeTrackingOn')
            , TableFulltextDocsProcessed            = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextDocsProcessed')
            , TableFulltextFailCount                = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextFailCount')
            , TableFulltextItemCount                = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextItemCount')
            , TableFulltextKeyColumn                = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextKeyColumn')
            , TableFulltextPendingChanges           = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextPendingChanges')
            , TableFulltextPopulateStatus           = OBJECTPROPERTYEX(o.[object_id], 'TableFulltextPopulateStatus')
            , TableFullTextSemanticExtraction       = OBJECTPROPERTYEX(o.[object_id], 'TableFullTextSemanticExtraction')
            , TableHasActiveFulltextIndex           = OBJECTPROPERTYEX(o.[object_id], 'TableHasActiveFulltextIndex')
            , TableHasCheckCnst                     = OBJECTPROPERTYEX(o.[object_id], 'TableHasCheckCnst')
            , TableHasClustIndex                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasClustIndex')
            , TableHasDefaultCnst                   = OBJECTPROPERTYEX(o.[object_id], 'TableHasDefaultCnst')
            , TableHasDeleteTrigger                 = OBJECTPROPERTYEX(o.[object_id], 'TableHasDeleteTrigger')
            , TableHasForeignKey                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasForeignKey')
            , TableHasForeignRef                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasForeignRef')
            , TableHasIdentity                      = OBJECTPROPERTYEX(o.[object_id], 'TableHasIdentity')
            , TableHasIndex                         = OBJECTPROPERTYEX(o.[object_id], 'TableHasIndex')
            , TableHasInsertTrigger                 = OBJECTPROPERTYEX(o.[object_id], 'TableHasInsertTrigger')
            , TableHasNonclustIndex                 = OBJECTPROPERTYEX(o.[object_id], 'TableHasNonclustIndex')
            , TableHasPrimaryKey                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasPrimaryKey')
            , TableHasRowGuidCol                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasRowGuidCol')
            , TableHasTextImage                     = OBJECTPROPERTYEX(o.[object_id], 'TableHasTextImage')
            , TableHasTimestamp                     = OBJECTPROPERTYEX(o.[object_id], 'TableHasTimestamp')
            , TableHasUniqueCnst                    = OBJECTPROPERTYEX(o.[object_id], 'TableHasUniqueCnst')
            , TableHasUpdateTrigger                 = OBJECTPROPERTYEX(o.[object_id], 'TableHasUpdateTrigger')
            , TableHasVarDecimalStorageFormat       = OBJECTPROPERTYEX(o.[object_id], 'TableHasVarDecimalStorageFormat')
            , TableInsertTrigger                    = OBJECTPROPERTYEX(o.[object_id], 'TableInsertTrigger')
            , TableInsertTriggerCount               = OBJECTPROPERTYEX(o.[object_id], 'TableInsertTriggerCount')
            , TableIsFake                           = OBJECTPROPERTYEX(o.[object_id], 'TableIsFake')
            , TableIsLockedOnBulkLoad               = OBJECTPROPERTYEX(o.[object_id], 'TableIsLockedOnBulkLoad')
            , TableIsMemoryOptimized                = OBJECTPROPERTYEX(o.[object_id], 'TableIsMemoryOptimized')
            , TableIsPinned                         = OBJECTPROPERTYEX(o.[object_id], 'TableIsPinned')
            , TableTextInRowLimit                   = OBJECTPROPERTYEX(o.[object_id], 'TableTextInRowLimit')
            , TableUpdateTrigger                    = OBJECTPROPERTYEX(o.[object_id], 'TableUpdateTrigger')
            , TableUpdateTriggerCount               = OBJECTPROPERTYEX(o.[object_id], 'TableUpdateTriggerCount')
            , UserDataAccess                        = OBJECTPROPERTYEX(o.[object_id], 'UserDataAccess')
            , TableHasColumnSet                     = OBJECTPROPERTYEX(o.[object_id], 'TableHasColumnSet')
            , Cardinality                           = OBJECTPROPERTYEX(o.[object_id], 'Cardinality')
            , TableTemporalType                     = OBJECTPROPERTYEX(o.[object_id], 'TableTemporalType')
    ) x
WHERE o.is_ms_shipped = 0;